  const showTab=name=>{document.body.dataset.tab=name;tabButtons.forEach(button=>button.classList.toggle('active',button.dataset.tab===name));window.scrollTo(0,0);flagTabs()};
  tabs.onclick=event=>{const button=event.target.closest('button[data-tab]');if(button)showTab(button.dataset.tab)};
  new MutationObserver(flagTabs).observe(document.querySelector('main'),{subtree:true,childList:true,attributes:true,attributeFilter:['class','hidden']});
  const zoom=Object.assign(document.createElement('div'),{className:'card-zoom',hidden:true,innerHTML:'<img alt="Enlarged card">'});document.body.append(zoom);zoom.onclick=()=>zoom.hidden=true;
